SELECT DISTINCT cs.canonical_smiles, sub_cr.compound_name AS substrate_compound_name, par_cr.compound_name AS parent_compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name FROM metabolism m JOIN compound_records sub_cr ON m.substrate_record_id = sub_cr.record_id JOIN compound_structures cs ON sub_cr.molregno = cs.molregno JOIN compound_records par_cr ON m.drug_record_id = par_cr.record_id WHERE m.enzyme_name = 'CYP2A6' ORDER BY cs.canonical_smiles, sub_cr.compound_name, par_cr.compound_name, m.met_conversion, m.pathway_key, m.organism, m.enzyme_name LIMIT 200
